const express = require('express');
const deltaService = require('../services/deltaService');

exports.startMigration = async (req, res) => {
  try {
    const { tables, validation } = req.body;
    if (!tables || tables.length === 0) {
      return res.status(400).json({ error: 'No tables provided' });
    }
    const jobId = await deltaService.startMigrationJob(tables, validation);
    res.status(200).json({ status: 'started', job_id: jobId });
  } catch (err) {
    console.error('Migration start error:', err);
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

exports.getMigrationStatus = async (req, res) => {
  try {
    const { job_id } = req.params;
    const status = await deltaService.getMigrationStatus(job_id);
    res.status(200).json(status);
  } catch (err) {
    console.error('Migration status error:', err);
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

